     * @return
     * @throws Exception
     */
    public String encrypt(String plainText) throws Exception {
        // 每次加密生成随机 IV
        String ivHex = generateRandomIV();
        // 转换密钥和IV
        byte[] keyBytes = hexStringToBytes(secretKeyHex);
        byte[] ivBytes = hexStringToBytes(ivHex);

        // 创建密钥规范
        SecretKeySpec keySpec = new SecretKeySpec(keyBytes, ALGORITHM_NAME);
        IvParameterSpec ivSpec = new IvParameterSpec(ivBytes);

        // 创建Cipher
        String transformation = ALGORITHM_NAME + "/" + MODE + "/" + PADDING;
        Cipher cipher = Cipher.getInstance(transformation, BouncyCastleProvider.PROVIDER_NAME);
        cipher.init(Cipher.ENCRYPT_MODE, keySpec, ivSpec);

        // 加密
        byte[] encryptedBytes = cipher.doFinal(plainText.getBytes(StandardCharsets.UTF_8));

        // Base64编码
        return Base64.getEncoder().encodeToString(encryptedBytes);
    }  
   /**
     * 解密
     * @param cipherText 需要解密的文本
     * @param headerIV 获取加密时header中IV
     * @return
     * @throws Exception
     */
    public String decrypt(String cipherText,String headerIV) throws Exception {
        // 获取当前请求的 IV（用于解密响应）
        String ivHex = headerIV;
        if (ivHex == null) {
            throw new IllegalStateException("未找到 IV 向量，请先调用 encrypt 方法");
        }

        // Base64解码
        byte[] encryptedBytes = Base64.getDecoder().decode(cipherText);

        // 转换密钥和IV
        byte[] keyBytes = hexStringToBytes(secretKeyHex);
        byte[] ivBytes = hexStringToBytes(ivHex);

        // 创建密钥规范
        SecretKeySpec keySpec = new SecretKeySpec(keyBytes, ALGORITHM_NAME);
        IvParameterSpec ivSpec = new IvParameterSpec(ivBytes);

        // 创建Cipher
        String transformation = ALGORITHM_NAME + "/" + MODE + "/" + PADDING;
        Cipher cipher = Cipher.getInstance(transformation, BouncyCastleProvider.PROVIDER_NAME);
        cipher.init(Cipher.DECRYPT_MODE, keySpec, ivSpec);

        // 解密
        byte[] decryptedBytes = cipher.doFinal(encryptedBytes);
        return new String(decryptedBytes, StandardCharsets.UTF_8);
    } 
