import com.alibaba.fastjson.JSONObject;

import java.io.BufferedReader;
import java.io.DataOutputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.net.HttpURLConnection;
import java.net.URL;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Base64;

public class QxyApiHttpDemo {
    // 对接地址apiHost
    private static final String url = "https://api.qixiangyun.com";
    private static final String AppKey = "1000****";//分配的appkey
    private static final String AppSecret = "*****************************************";//分配的AppSecret
    private static String access_token = null;

    /**
     * 获取access_token
     * @return
     * @throws Exception
     */
    private static String getAccessToken() throws Exception {
        String tokenUrl = url + "/v2/public/oauth2/login";
        String body = "{\"grant_type\":\"client_credentials\",\"client_appkey\":\"" + AppKey + "\",\"client_secret\":\"" + md5(AppSecret) + "\"}";

        HttpURLConnection conn = (HttpURLConnection) new URL(tokenUrl).openConnection();
        conn.setRequestMethod("POST");
        conn.setRequestProperty("Content-Type", "application/json;charset=UTF-8");
        conn.setDoOutput(true);

        try (DataOutputStream wr = new DataOutputStream(conn.getOutputStream())) {
            wr.write(body.getBytes(StandardCharsets.UTF_8));
        }

        String response = readResponse(conn);
        System.out.println("示例获取token结果:" + response);
        JSONObject resultJson = JSONObject.parseObject(response);
        JSONObject dataJson = resultJson.getJSONObject("data");
        return dataJson.getString("access_token");
    }

    /**
     * http发送业务请求
     * @param path
     * @param body
     * @return
     * @throws Exception
     */
    private static void sendBusinessRequest(String path, String body) throws Exception {
        String fullUrl = url + path;
        String req_date = String.valueOf(System.currentTimeMillis());
        String contentMd5 = md5(body);

        // 生成待签名字符串并进行UTF-8编码
        String toSign = "POST_" + contentMd5 + "_" + req_date + "_" + access_token + "_" + AppSecret;
        byte[] toSignBytes = toSign.getBytes(StandardCharsets.UTF_8);
        String toSignUtf8 = new String(toSignBytes, StandardCharsets.UTF_8);

        // 生成MD5加密结果
        String md5Result = md5(toSignUtf8);

        // 生成Base64编码结果
        String base64Result = base64Encode(md5Result);

        // 生成req_sign
        String req_sign = "API-SV1:" + AppKey + ":" + base64Result;

        HttpURLConnection conn = (HttpURLConnection) new URL(fullUrl).openConnection();
        conn.setRequestMethod("POST");
        conn.setRequestProperty("Content-Type", "application/json;charset=UTF-8");
        conn.setRequestProperty("access_token", access_token);
        conn.setRequestProperty("req_date", req_date);
        conn.setRequestProperty("req_sign", req_sign);
        conn.setDoOutput(true);
        byte[] outputInBytes = body.getBytes(StandardCharsets.UTF_8);
        OutputStream os = conn.getOutputStream();
        os.write(outputInBytes);
        os.close();
        // 获取服务器响应代码
        int responseCode = conn.getResponseCode();
        // 读取服务器响应内容
        if (responseCode == HttpURLConnection.HTTP_OK) {
            String result = readResponse(conn);
            System.out.println("示例返回结果:"+result);
        }else {
            //异常处理
        }
        conn.disconnect();
    }

    private static String readResponse(HttpURLConnection conn) throws Exception {
        try (BufferedReader in = new BufferedReader(new InputStreamReader(conn.getInputStream()))) {
            String inputLine;
            StringBuilder content = new StringBuilder();
            while ((inputLine = in.readLine()) != null) {
                content.append(inputLine);
            }
            return content.toString();
        }
    }

    private static String md5(String input) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] digest = md.digest(input.getBytes(StandardCharsets.UTF_8));
        return bytesToHex(digest);
    }

    private static String base64Encode(String input) {
        byte[] inputBytes = input.getBytes(StandardCharsets.UTF_8);
        return Base64.getEncoder().encodeToString(inputBytes);
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder hexString = new StringBuilder();
        for (byte b : bytes) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }

    public static void main(String[] args) {
        try {
            // 1. 获取access_token
            access_token = getAccessToken();
            //这里获取到的access_token需要缓存到本地缓存中再使用，频繁请求login接口会被限制。
            // 2. 请求业务接口示例: 发票查验接口
            String path = "/v2/invoice/cy/zzsfpCy"; // 自定义业务接口路径
            String params = "{\"cyList\":[{\"fpdm\":\"34******30\",\"fphm\":\"17****68\",\"kprq\":\"2021-11-01\",\"je\":1421.63}]}";
            sendBusinessRequest(path, params); // 请求body参数
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
