```python
import hashlib
import base64
import json
import requests
from datetime import datetime

# 对接地址apiHost
url = "https://api.qixiangyun.com"
AppKey = "1000****"  # 分配的appkey
AppSecret = "***********************"  # 分配的AppSecret
access_token = None

def md5(input_string):
    md = hashlib.md5()
    md.update(input_string.encode('utf-8'))
    return md.hexdigest()

def base64_encode(input_string):
    input_bytes = input_string.encode('utf-8')
    return base64.b64encode(input_bytes).decode('utf-8')
# 获取access_token
def get_access_token():
    global access_token
    token_url = f"{url}/v2/public/oauth2/login"
    body = {
        "grant_type": "client_credentials",
        "client_appkey": AppKey,
        "client_secret": md5(AppSecret)
    }

    response = requests.post(token_url, json=body)
    response.raise_for_status()
    result_json = response.json()
    data_json = result_json["data"]
    access_token = data_json["access_token"]
    print(f"示例获取token结果: {response.text}")
#发起业务请求
def send_business_request(path, body):
    full_url = f"{url}{path}"
    req_date = str(int(datetime.now().timestamp() * 1000))
    content_md5 = md5(body)

    # 生成待签名字符串并进行UTF-8编码
    to_sign = f"POST_{content_md5}_{req_date}_{access_token}_{AppSecret}"
    to_sign_utf8 = to_sign.encode('utf-8')

    # 生成MD5加密结果
    md5_result = md5(to_sign_utf8.decode('utf-8'))

    # 生成Base64编码结果
    base64_result = base64_encode(md5_result)

    # 生成req_sign
    req_sign = f"API-SV1:{AppKey}:{base64_result}"

    headers = {
        "Content-Type": "application/json;charset=UTF-8",
        "access_token": access_token,
        "req_date": req_date,
        "req_sign": req_sign
    }

    response = requests.post(full_url, headers=headers, data=body)
    if response.status_code == 200:
        print(f"示例返回结果: {response.text}")
    else:
        # 异常处理
        print(f"请求失败: {response.status_code}, {response.text}")

def main():
    try:
        # 1. 获取access_token
        get_access_token()
        # 获取到的access_token做缓存处理
        # 2. 请求业务接口示例：数电开票-已开发票列表查询
        path = "/v2/invoice/qdfp/fpcx"  # 自定义业务接口路径
        # 按照接口文档定义的参数进行参数封装
        params = json.dumps({
            "action": "fpcx",
            "nsrsbh": "真实税号",      
            "data": {
                "pageIndex": 0,
                "pageSize": 10,
                "params": {
                    "kprqq": "2024-09-01",
                    "kprqz": "2024-09-15",
                    "dfnsrsbh": "",
                    "dfnsrmc": "",
                    "fphm": ""
                }
            }
        })
        send_business_request(path, params)
    except Exception as e:
        print(f"发生异常: {e}")

if __name__ == "__main__":
    main()

```
